-- Fictional identities and provider IDs; no HTTP, real charges, email or retained data.
begin;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();inactive uuid:=gen_random_uuid();r uuid;
 c1 uuid:=gen_random_uuid();c2 uuid:=gen_random_uuid();p jsonb;x jsonb;y jsonb;cfg jsonb;lease uuid;credential_uuid uuid;job jsonb;
begin
 select id into r from public.duuk_roles order by name limit 1;
 insert into auth.users(id,email) values(a,a::text||'@test.invalid'),(b,b::text||'@test.invalid'),(inactive,inactive::text||'@test.invalid');
 insert into public.duuk_profiles(id,name,email,role_id,active,is_super_admin) values
 (a,'Billing fixture admin',a::text||'@test.invalid',r,true,true),(b,'Billing fixture denied',b::text||'@test.invalid',r,true,false),(inactive,'Billing fixture inactive',inactive::text||'@test.invalid',r,false,true);
 insert into public.duuk_user_permissions(user_id,permission,allowed) values(b,'billing',false);
 -- Hide configurations inside rollback, without touching real histories.
 delete from duuk_private.billing_jobs;
 delete from duuk_private.billing_charges;
 delete from duuk_private.billing_config;
 begin perform public.duuk_billing_backend(b,'status');raise exception 'Denied finance allowed';exception when sqlstate 'PT403' then null;end;
 begin perform public.duuk_billing_backend(inactive,'status');raise exception 'Inactive allowed';exception when sqlstate 'PT403' then null;end;
 begin perform public.duuk_billing_backend(null,'configure');raise exception 'Worker configured account';exception when sqlstate 'PT403' then null;end;
 p:=jsonb_build_object('api_key','fixture-secret-api-1234567890','webhook_token',repeat('f',64),'webhook_hash',repeat('a',64),'account_id','fixture-account','account_name','DUUK fictícia','account_status','APPROVED','contact_email','technical@test.invalid');
 begin perform public.duuk_billing_backend(a,'configure',p||'{"environment":"production"}');raise exception 'Production without fees accepted';exception when sqlstate 'PT400' then null;end;
 perform public.duuk_billing_backend(a,'configure',p);
 cfg:=public.duuk_billing_backend(a,'credentials');credential_uuid:=(select credential_id from duuk_private.billing_config where environment='sandbox');
 if (select v.secret::text from vault.secrets v where v.id=credential_uuid) like '%fixture-secret-api%' then raise exception 'Plaintext secret at rest';end if;
 perform public.duuk_billing_backend(a,'config_ready',jsonb_build_object('generation',cfg->>'generation','webhook_id','hook_fixture'));
 x:=public.duuk_billing_backend(a,'status');
 if x::text like '%secret%' or x::text like '%api_key%' or x::text like '%webhook_token%' then raise exception 'Public secret leaked';end if;
 if (x->>'connected')::boolean is not true then raise exception 'Configuration not ready';end if;
 p:=jsonb_build_object('generation',cfg->>'generation','id',c1,'title','Fixture film','client_name','Fictional payer','amount_cents',150050,'due_date',current_date,'method','PIX','payer_hash',repeat('b',64),'request_hash',repeat('c',64));
 x:=public.duuk_billing_backend(a,'begin_create',p);if (x->>'execute')::boolean is not true then raise exception 'Creation not claimed';end if;
 y:=public.duuk_billing_backend(a,'begin_create',p);if (y->>'execute')::boolean is not false then raise exception 'Duplicate executed';end if;
 begin perform public.duuk_billing_backend(a,'begin_create',p||jsonb_build_object('request_hash',repeat('d',64)));raise exception 'Changed attempt accepted';exception when sqlstate 'PT409' then null;end;
 begin perform public.duuk_billing_backend(a,'begin_create',p||jsonb_build_object('id',c2));raise exception 'Concurrent creation allowed';exception when sqlstate 'PT409' then null;end;
 perform public.duuk_billing_backend(a,'customer_start',p);
 perform public.duuk_billing_backend(a,'customer_saved',p||'{"customer_id":"cus_fixture"}');
 perform public.duuk_billing_backend(a,'payment_start',p);
 begin perform public.duuk_billing_backend(a,'payment_start',p);raise exception 'Payment POST repeated';exception when sqlstate 'PT409' then null;end;
 p:=p||jsonb_build_object('customer_id','cus_fixture','external_reference','duuk:'||c1,'payment_id','pay_fixture','status','PENDING','invoice_url','https://sandbox.asaas.com/i/fixture');
 begin perform public.duuk_billing_backend(a,'created',p||'{"amount_cents":999}');raise exception 'Wrong amount accepted';exception when sqlstate 'PT409' then null;end;
 begin perform public.duuk_billing_backend(a,'created',p-'customer_id');raise exception 'Null customer accepted';exception when sqlstate 'PT409' then null;end;
 x:=public.duuk_billing_backend(a,'created',p);
 if x ? 'payer_hash' or x ? 'request_hash' or x ? 'customer_id' or x ? 'sync_lease' then raise exception 'Internal charge data leaked';end if;
 x:=public.duuk_billing_backend(a,'list',jsonb_build_object('month',to_char(current_date,'YYYY-MM')));
 if jsonb_array_length(x->'items')<>1 or (x#>>'{stats,open_cents}')::bigint<>150050 then raise exception 'Monthly list/stats wrong';end if;
 begin perform public.duuk_billing_backend(a,'sync_apply',p||'{"status":"RECEIVED"}');raise exception 'Null lease accepted';exception when sqlstate 'PT409' then null;end;
 x:=public.duuk_billing_backend(a,'sync_claim',p);lease:=(x->>'lease_id')::uuid;
 begin perform public.duuk_billing_backend(a,'sync_claim',p);raise exception 'Concurrent sync accepted';exception when sqlstate 'PT409' then null;end;
 begin perform public.duuk_billing_backend(a,'sync_apply',p||jsonb_build_object('lease_id',lease,'payment_id','pay_wrong'));raise exception 'Payment changed';exception when sqlstate 'PT409' then null;end;
 perform public.duuk_billing_backend(a,'sync_apply',p||jsonb_build_object('lease_id',lease,'status','CONFIRMED'));
 x:=public.duuk_billing_backend(a,'list',jsonb_build_object('month',to_char(current_date,'YYYY-MM')));
 if (x#>>'{stats,received_cents}')::bigint<>0 or (x#>>'{stats,confirmed_cents}')::bigint<>150050 then raise exception 'Confirmation counted as settlement';end if;
 x:=public.duuk_billing_backend(a,'sync_claim',p);lease:=(x->>'lease_id')::uuid;
 perform public.duuk_billing_backend(a,'sync_apply',p||jsonb_build_object('lease_id',lease,'status','RECEIVED','has_refunds',true));
 x:=public.duuk_billing_backend(a,'list',jsonb_build_object('month',to_char(current_date,'YYYY-MM')));
 if (x#>>'{stats,received_cents}')::bigint<>0 then raise exception 'Refunded amount counted';end if;
 -- Provider metadata is applied only under the same generation, amount and lease guards.
 x:=public.duuk_billing_backend(a,'sync_claim',p);lease:=(x->>'lease_id')::uuid;
 x:=public.duuk_billing_backend(a,'sync_apply',p||jsonb_build_object('lease_id',lease,'title','Updated provider description','due_date',current_date+1));
 if x->>'title'<>'Updated provider description' or (x->>'due_date')::date<>current_date+1 then raise exception 'Canonical metadata lost';end if;
 x:=public.duuk_billing_backend(a,'sync_claim',p);lease:=(x->>'lease_id')::uuid;
 x:=public.duuk_billing_backend(a,'sync_apply',p||jsonb_build_object('lease_id',lease,'title',null,'due_date',null));
 if x->>'title'<>'Updated provider description' or (x->>'due_date')::date<>current_date+1 then raise exception 'Null metadata erased values';end if;
 p:=jsonb_build_object('config_id',cfg->>'config_id','payment_id','pay_fixture','event_id','evt_fixture','event_type','PAYMENT_RECEIVED');
 perform public.duuk_billing_backend(null,'enqueue',p);perform public.duuk_billing_backend(null,'enqueue',p);
 perform public.duuk_billing_backend(null,'enqueue',p||'{"event_id":"evt_foreign","payment_id":"pay_foreign"}');
 if (select count(*) from duuk_private.billing_jobs)<>1 then raise exception 'Event duplicate or foreign payment queued';end if;
 job:=public.duuk_billing_backend(null,'jobs');if jsonb_array_length(job)<>1 or job#>>'{0,environment}'<>'sandbox' then raise exception 'Queue claim wrong';end if;
 if jsonb_array_length(public.duuk_billing_backend(null,'jobs'))<>0 then raise exception 'Job double claimed';end if;
 begin perform public.duuk_billing_backend(a,'configure',jsonb_build_object('api_key','fixture-secret-api-1234567890','webhook_token',repeat('f',64),'account_id','other-account'));raise exception 'Account replaced with history';exception when sqlstate 'PT409' then null;end;
 perform public.duuk_billing_backend(a,'disconnect');
 if exists(select 1 from vault.secrets where id=credential_uuid) then raise exception 'Disconnect retained API secret';end if;
 if not exists(select 1 from duuk_private.billing_charges where id=c1) then raise exception 'Disconnect lost history';end if;
 if has_function_privilege('anon','public.duuk_billing_backend(uuid,text,jsonb)','execute') or has_function_privilege('authenticated','public.duuk_billing_backend(uuid,text,jsonb)','execute') then raise exception 'RPC exposed';end if;
 execute 'set local role authenticated';
 begin perform * from duuk_private.billing_charges;raise exception 'Browser read private charges';exception when insufficient_privilege then null;end;
 execute 'reset role';
end $$;
rollback;
